  "水槽前で戦いから離れた本音を交わす。": "In front of the aquarium, they exchange their true feelings away from the battle.",
  "屋台の光の中、結界のほころびを塞ぐ。": "In the light of the stall, I close the frayed barrier.",
  "街のイルミネーションに異世界信号が混じる。": "Otherworldly signals mix with the illuminations of the city.",
  "まっすぐ気持ちを伝える": "express your feelings directly",
