  "開けた筆箱の中で、小さな竜が鉛筆を抱えて気持ちよさそうに眠っていた。": "Inside the open pencil case, a small dragon was sleeping comfortably, holding a pencil in its arms.",
  "二人きりの寄り道へ誘う": "Invite me to take a detour just the two of us",
