  "二人の場所を作ろうと言う": "I say let's make a place for the two of us.",
  "抱え込まないでと言う": "I say don't hold me",
  "必ず一緒に抜け出す": "We'll definitely get out together",
  "使命も日常も守ると誓う": "I vow to protect my mission and my daily life.",
  "同じ場所に立ちたいと言う": "say they want to stand in the same place",
  "無理に近づかなくていいと言う": "I tell her that I don't have to force myself to approach her.",
