  "ファンシーな独裁に終止符を打つ時だ。チャックの位置を見抜き、校長を現実へ引き戻せ。": "It's time to put an end to fancy dictatorships. Find out where Chuck is and bring the principal back to reality.",
  "ゼリーは褒められるほど増え、廊下をぷるぷる塞いでいく。かわいいが、通れない。おいしそうだが、成分表がない。": "The more the jelly is praised, the more it grows and blocks the hallway. It's cute, but I can't pass it. It looks delicious, but there is no ingredient list.",
