  "星災の女王": "ほしわざわいのじょおう",
  "放課後の握手同盟": "ほうかごのあくしゅどうめい",
  "校門の夕焼けの前で、別々に戦っていた二人が初めて同じ目的に手を伸ばす。": "こうもんのゆうやけのまえで、べつべつにたたかっていたににんがはじめておなじもくてきにてをのばす。",
  "夜の光る自販機": "よるのひかるじはんき",
  "校舎裏の自販機が、見たことのない飲み物を一つだけ光らせている。": "こうしゃうらのじはんきが、みたことのないのみものをひとつだけひからせている。",
  "屋上告白と小さな門": "おくじょうこくはくとちいさなもん",
  "言いかけた言葉の上で、小さな異世界の門がぽんと開いた。": "いいかけたことばのうえで、ちいさないせかいのもんがぽんとひらいた。",
  "嵐の日の即席めん": "あらしのひのそくせきめん",
  "帰れない教室で、友人たちと分けた湯気が妙に心強い。": "かえれないきょうしつで、ゆうじんたちとわけたゆげがみょうにこころづよい。",
  "重力の軽い廊下": "じゅうりょくのかるいろうか",
  "ロッカーと上履きが少し浮き、廊下全体が寝ぼけたように揺れている。": "ロッカーとうわばきがすこしうき、ろうかぜんたいがねぼけたようにゆれている。",
  "本の中の小さな森": "ほんのなかのちいさなもり",
  "図書室で開いた本のページに、指先ほどの森と風が生まれている。": "としょしつでひらいたほんのページに、ゆびさきほどのもりとかぜがうまれている。",
  "伝説バトンのリレー": "でんせつバトンのリレー",
  "リレーのバトンがまるで聖剣のように光り、走者の背中を押す。": "リレーのバトンがまるできよしけんのようにひかり、そうしゃのせなかをおす。",
  "天文部の異世界観測": "てんもんぶのいせかいかんそく",
  "望遠鏡の先には星ではなく、雲に浮かぶ城が映っていた。": "ぼうえんきょうのさきにはほしではなく、くもにうかぶしろがうつっていた。",
  "紙ドラゴンの生徒会室": "かみドラゴンのせいとかいしつ",
  "山積みの資料が折り重なり、紙のドラゴンになって議題を守っている。": "やまづみのしりょうがおりかさなり、かみのドラゴンになってぎだいをまもっている。",
  "バス停で片方ずつイヤホンを分けると、雨音まで少し優しく聞こえた。": "バスとまでかたほうずつイヤホンをわけると、あめおんまですこしやさしくきこえた。",
